/* Capacity metrics, rule-based bottleneck insights, auto-generated actions */
function commandCentreCard(){
 const p=buildAgentPlan(),m=p.money,top=p.options.find(o=>o.id===p.recommended);
 return `<div class="card" style="border-top:4px solid #c53030;margin-bottom:14px"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><h3 style="margin:0">Command centre · Cost of doing nothing</h3><span class="tag red">Placeholder rupee assumptions</span></div>
 <div class="grid three" style="margin-top:12px"><div><div class="muted smalltext">Cost of doing nothing</div><div class="metric"><div class="value">${inr(m.costPerDay)}<span style="font-size:14px;font-weight:650"> /day</span></div></div></div><div><div class="muted smalltext">Idle capacity (${p.b.blocked} blocked × ${inr(m.bedDay)})</div><div class="metric"><div class="value" style="font-size:22px">${inr(m.idle)}</div></div></div><div><div class="muted smalltext">Admissions at risk (${m.atRiskAdmits} × ${inr(m.admission)})</div><div class="metric"><div class="value" style="font-size:22px">${inr(m.atRisk)}</div></div></div></div>
 <p class="smalltext" style="margin-top:8px">${top&&top.perHour>0?`Best use of effort: <b>Option ${top.id}</b> at <b>${inr(top.perHour)}</b> demand-backed revenue per hour of effort.`:"No option currently shows demand-backed revenue per hour of effort."}</p>
 <form id="moneyForm" style="margin-top:10px"><div class="grid three"><div class="field"><label for="moneyBedDay">₹ per blocked bed-day</label><input id="moneyBedDay" name="bedDay" type="number" min="0" step="100" value="${m.bedDay}" required></div><div class="field"><label for="moneyAdmission">₹ per admission</label><input id="moneyAdmission" name="admission" type="number" min="0" step="100" value="${m.admission}" required></div><div class="field" style="align-self:end"><button style="width:100%">Save assumptions</button></div></div></form>
 <p class="muted smalltext">Both rupee figures are placeholders, not hospital financial data. Cost per day = blocked beds × ₹ per bed-day + min(blocked beds, patients waiting) × ₹ per admission, assuming one waiting patient could be admitted per blocked bed per day. Edit them to match your hospital.</p></div>`;
}
function regularAvailableBeds(){return Math.max(0,db.beds.total-db.beds.occupied-db.beds.blocked-db.beds.cleaning-db.beds.clearance)}
function emergencyRoomShouldOpen(){return regularAvailableBeds()===0 && db.beds.waiting>0}
function emergencyBedsAvailable(){return Math.max(0,db.beds.emergencyRoomTotal-db.beds.emergencyRoomOccupied)}
function availableBeds(){return regularAvailableBeds()+(db.beds.emergencyRoomActive?emergencyBedsAvailable():0)}
function slots(){return db.doctors.filter(d=>d.status==="Available").reduce((s,d)=>s+n(d.slots),0)}
function pendingDischarges(){return db.discharges.filter(d=>d.approval!=="Approved").length}
function delayedLabs(){return db.labs.reduce((s,l)=>s+n(l.delayed),0)}
function shortages(){return db.staff.reduce((s,x)=>s+n(x.shortage),0)}
function insightsBase(){
let a=[],b=db.beds;
if(b.blocked>0&&db.discharges.some(d=>d.documents==="Pending"))a.push({priority:"High",issue:"Blocked beds and pending discharge paperwork",departments:"Bed Management + Discharge Coordination",data:`${b.blocked} blocked beds; ${db.discharges.filter(d=>d.documents==="Pending").length} discharge cases with pending documents`,cause:"Pending documentation may be contributing to delayed bed release.",action:"Review document completion and confirm each case with authorised staff."});
if(delayedLabs()>0&&pendingDischarges()>0)a.push({priority:"High",issue:"Laboratory delays may affect discharge workflow",departments:"Diagnostics and Laboratories + Discharge Coordination",data:`${delayedLabs()} delayed tests; ${pendingDischarges()} discharges not finally approved`,cause:"Some discharge workflows may be waiting for investigation results; verify case by case.",action:"Ask the lab team to review delayed reports and notify the responsible clinical team."});
if(shortages()>0)a.push({priority:shortages()>=4?"High":"Medium",issue:"Staffing below required coverage",departments:"Staff and Rosters",data:`${shortages()} staff positions currently short across recorded shifts`,cause:"Reduced staffing may slow operational throughput in affected departments.",action:"Review shift coverage and escalate staffing support to the roster lead."});
let waiting=db.doctors.reduce((s,d)=>s+n(d.waiting),0);
if(waiting>=20&&slots()<=10)a.push({priority:"High",issue:"Doctor availability may be a bottleneck",departments:"Appointments and Doctors",data:`${waiting} patients waiting; ${slots()} available appointment slots`,cause:"Current waiting demand is high relative to recorded appointment slots.",action:"Review doctor availability and capacity; do not exceed each doctor's entered capacity."});
if(regularAvailableBeds()===0&&b.waiting>0)a.push({priority:"Critical",issue:"Regular beds exhausted — emergency overflow room needs review",departments:"Bed Management + Medical Superintendent",data:`0 regular beds available; ${b.waiting} patients waiting; overflow room ${db.beds.emergencyRoomActive?"open":"closed"}; ${emergencyBedsAvailable()} free overflow beds`,cause:"Recorded regular capacity is exhausted while demand remains.",action:"Alert the authorised on-duty lead and Superintendent. Verify triage, staffing, equipment and safe placement before activating overflow beds."});
if(availableBeds()<=10&&b.waiting>0)a.push({priority:"Critical",issue:"Low available bed capacity with patients waiting",departments:"Bed Management + Discharge Coordination",data:`${availableBeds()} available beds; ${b.waiting} patients waiting, including ${b.emergency} emergency cases`,cause:"Available capacity may be insufficient for current waiting demand.",action:"Escalate for an operational bed-status review and verify safe, authorised next steps."});
if(!a.length)a.push({priority:"Low",issue:"No rule-based bottleneck detected",departments:"All departments",data:"Current entered demo data does not meet configured alert rules.",cause:"This does not prove that there are no operational issues.",action:"Continue routine monitoring and keep department information current."});
return a}
function autoActionsBase(){let existing=new Set(db.actions.filter(a=>a.status!=="Completed").map(a=>a.title));for(const x of insights()){if(x.priority==="Low")continue;let title=x.issue;if(!existing.has(title)){db.actions.unshift({id:id("ACT"),title:x.issue,department:x.departments,priority:x.priority,description:x.action,assigned:"Unassigned",status:"Open",created:now(),auto:true});existing.add(title)}}}
